// Pour régénérer après une mise à jour du jeu : python3 scripts/generer-succes-donjons.py

/** `icone` : numéro de l'icône du challenge (public/icones/challenges/<n>.webp), 0 pour la simple victoire. */
export type Succes = { id: string; libelle: string; description: string; points: number; icone: number };
/** `icone` : fichier de public/icones/donjons/ (icône du succès dans le jeu, ou portrait du boss), vide si aucune. */
export type DonjonSucces = { nom: string; niveau: number; boss: string; icone: string; succes: Succes[] };

const S = (id: number, libelle: string, description: string, points: number, icone: number): Succes => ({ id: `ach:${id}`, libelle, description, points, icone });
const D = (nom: string, niveau: number, boss: string, icone: string, succes: Succes[]): DonjonSucces => ({ nom, niveau, boss, icone, succes });

