export const TRANCHES = ["1 à 50", "51 à 100", "101 à 150", "151 à 199", "200"] as const;
export type Tranche = (typeof TRANCHES)[number];

/** Tranche de niveau d'un donjon (d'après son niveau conseillé). Le niveau 200, très fourni, a sa propre tranche. */
export function trancheDe(niveau: number): Tranche {
  if (niveau <= 50) return "1 à 50";
  if (niveau <= 100) return "51 à 100";
  if (niveau <= 150) return "101 à 150";
  if (niveau < 200) return "151 à 199";
  return "200";
}

/** Clé unique d'une ligne (un donjon peut avoir plusieurs boss, donc plusieurs lignes). */
export const cleDonjon = (d: DonjonSucces) => `${d.nom}|${d.boss}`;

export const TOTAL_SUCCES = DONJONS_SUCCES.reduce((n, d) => n + d.succes.length, 0);

/** Nom simplifié pour comparer : sans accents, sans parenthèses, sans article en tête. */
export function normaliser(nom: string): string {
  return nom
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\(.*?\)/g, "")
    .replace(/^(le |la |l')/, "")
    .replace(/\s+/g, " ")
    .trim();
}

// Noms d'étapes du site qui diffèrent du nom du boss dans le jeu.
const ALIAS: Record<string, string> = { "rasboul majeur": "silf le rasboul majeur", tynril: "tynrils" };

const PAR_BOSS = new Map(DONJONS_SUCCES.map((d) => [normaliser(d.boss), d]));

/** Donjon (et ses succès) du boss d'une étape « boss » (Tour du monde, Emma Tom Pouce, Frigost). */
export function donjonDuBoss(nomEtape: string): DonjonSucces | undefined {
  const n = normaliser(nomEtape);
  return PAR_BOSS.get(ALIAS[n] ?? n);
}

export const SUCCES_PAR_ID = new Map(DONJONS_SUCCES.flatMap((d) => d.succes.map((s) => [s.id, { succes: s, donjon: d }] as const)));
